import {useState} from 'react'
import {Button, Dialog, Heading, Stack} from '@primer/react'
import type {HeadingTag} from '../types/heading-tag'
import {clsx} from 'clsx'
import styles from './PaymentSummary.module.css'

export interface PaymentSummaryProps {
  title: string
  currentPayment: string
  description?: string
  headingAs?: HeadingTag
  moreDetailsBody?: React.ReactNode
  moreDetailsButtons?: React.ReactNode
  /** Product name used for accessible button labels (e.g., "Enterprise Cloud", "Copilot") */
  productName?: string
}

export function PaymentSummary({
  title,
  currentPayment,
  description,
  headingAs = 'h3',
  moreDetailsBody,
  moreDetailsButtons,
  productName,
}: PaymentSummaryProps) {
  const [isDialogOpen, setIsDialogOpen] = useState(false)

  return (
    <Stack
      direction="vertical"
      gap="none"
      padding="none"
      align="start"
      className={styles.wrapper}
      data-testid="payment-summary"
    >
      <Stack
        direction="horizontal"
        padding="none"
        align="start"
        data-testid="payment-summary-header"
        className={styles.header}
      >
        <Stack.Item grow className={styles.titleItem}>
          <Heading as={headingAs} data-testid="payment-summary-title" className={clsx('f5', styles.titleHeader)}>
            {title}
          </Heading>
        </Stack.Item>
        {moreDetailsBody != null && (
          <Stack.Item className={styles.moreDetailsItem}>
            <Button
              aria-label={`More details about ${productName ? `${productName} ` : ''}${title.toLowerCase()}`}
              data-testid="more-details-btn"
              variant="invisible"
              className={styles.moreDetailsButton}
              onClick={() => setIsDialogOpen(true)}
            >
              More details
            </Button>
            {isDialogOpen && (
              <Dialog title={title} width="large" onClose={() => setIsDialogOpen(false)}>
                {moreDetailsBody}
                <div className="d-flex flex-justify-end gap-2 mt-2">
                  {moreDetailsButtons != null && moreDetailsButtons}
                  <Button className="btn-primary" onClick={() => setIsDialogOpen(false)}>
                    Done
                  </Button>
                </div>
              </Dialog>
            )}
          </Stack.Item>
        )}
      </Stack>
      <Stack direction="vertical" padding="none" gap="none" className="gap-1" data-testid="usage-summary-item">
        <Stack.Item grow>
          <div className="f3 text-normal lh-default" data-testid="billable-amount">
            {currentPayment}
          </div>
        </Stack.Item>
        <Stack.Item>
          <div className={clsx('f6 color-fg-muted', styles.descLineHeight)} data-testid="billable-amount-description">
            {description}
          </div>
        </Stack.Item>
      </Stack>
    </Stack>
  )
}
